.ds-player { position: relative; min-height: 240px; width: 100%; container-type: inline-size; }
.ds-player {
      --cueweave-ink: #eeeeee;
      --cueweave-secondary: #d5d5d5;
      --cueweave-accent: #ff9859;
      --cueweave-action-ink: #202020;
      font-size: 16px;
      color-scheme: dark;
    }
    .ds-player-caption {
      position: absolute;
      bottom: var(--cueweave-position, 9%);
      left: 50%;
      transform: translateX(-50%);
      display: none;
      box-sizing: border-box;
      width: max-content;
      max-width: 90%;
      padding: 0.4em 0.7em 0.45em;
      border: 0;
      border-radius: 8px;
      color: var(--cueweave-ink);
      background: rgb(26 26 26 / var(--cueweave-caption-background-opacity, 0.8));
      font-family: "MiSans", "Mi Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
      font-size: calc(clamp(16px, 2.5cqi, 32px) * var(--cueweave-font-scale, 1) * var(--cueweave-fit-scale, 1));
      font-weight: 600;
      line-height: 1.42;
      text-align: center;
      text-wrap: balance;
      overflow-wrap: anywhere;
      text-shadow: 0 2px 3px rgb(0 0 0 / 80%);
    }
    .ds-player-caption[data-backing="false"] {
      -webkit-text-stroke: 1px rgb(0 0 0 / 85%);
      paint-order: stroke fill;
      text-shadow: 0 1px 2px #000, 0 2px 4px #000;
    }
    .ds-player.controls-visible .ds-player-caption {
      bottom: max(var(--cueweave-position, 9%), 60px);
    }
    .ds-player-caption[data-visible="true"] {
      display: flex;
      flex-direction: column;
      align-items: stretch;
      gap: 0.2em;
    }
    .ds-player-translation { display: none; }
    .ds-player-caption[data-translated="true"] .ds-player-translation { display: block; }
    .ds-player-caption[data-translated="true"] .ds-player-source {
      color: var(--cueweave-secondary);
      font-size: calc(1em * var(--cueweave-source-font-scale, 0.68));
      font-weight: 400;
      line-height: 1.4;
    }
    .ds-player-caption[data-mode="translation"] .ds-player-source { display: none; }
    .ds-player-caption[data-mode="source"] .ds-player-translation { display: none; }
    .ds-player-caption[data-mode="source"] .ds-player-source {
      color: inherit;
      font-size: inherit;
      font-weight: inherit;
      line-height: inherit;
    }
    .ds-player-caption[data-mode="bilingual"][data-order="source-first"] .ds-player-source { order: -1; }
    .ds-player-translate-action {
      display: none;
      align-items: center;
      justify-content: center;
      align-self: center;
      box-sizing: border-box;
      min-height: 32px;
      max-width: 100%;
      margin: 6px 0 0;
      padding: 6px 12px;
      border: 1px solid transparent;
      border-radius: 8px;
      background: var(--cueweave-accent);
      color: var(--cueweave-action-ink);
      font: 600 13px/1.4 "MiSans", "Mi Sans", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
      text-shadow: none;
      -webkit-text-stroke: 0;
      pointer-events: auto;
      cursor: pointer;
      transition: background-color 160ms ease-out;
    }
    .ds-player-caption[data-action="true"] .ds-player-translate-action { display: inline-flex; }
    .ds-player-translate-action:hover:not(:disabled) { background: #ffb184; }
    .ds-player-translate-action:active:not(:disabled) { background: #ff9859; }
    .ds-player-translate-action:focus-visible {
      outline: 2px solid var(--cueweave-accent);
      outline-offset: 3px;
    }
    .ds-player-translate-action:disabled {
      color: var(--cueweave-secondary);
      border-color: #898989;
      background: #303030;
      cursor: default;
    }
    @media (prefers-reduced-motion: reduce) {
      .ds-player-translate-action { transition: none; }
    }
    @media (forced-colors: active) {
      .ds-player-caption { background: Canvas; color: CanvasText; text-shadow: none; }
      .ds-player-caption .ds-player-source { color: CanvasText; }
      .ds-player-translate-action { border-color: ButtonText; }
    }
